questionvariables.text:
/* Design: counting squares under a curve. Entries [W, c0, c1, c2, F, P, dx, dy]: the region under y = c0 + c1 u + c2 u^2 (grid units), 0 <= u <= W. Every part square is 7% to 93% covered; the general-feedback JavaScript reproduces the counts on every entry. Curves bend both ways (5 each). Source: original. */
L: [[8,5.0,0.7,-0.1,42,8,10,5],[7,3.2,0.9,-0.1,30,7,5,2],[7,2.4,-0.5,0.1,12,7,20,10],[6,4.0,-0.3,0.1,22,6,4,3],[8,1.6,0.9,-0.1,20,9,10,10],[7,3.0,-0.5,0.1,16,8,4,2],[6,4.8,0.3,-0.15,18,9,5,5],[8,3.2,0.0,0.05,30,9,20,5],[7,4.6,-0.7,0.1,23,7,3,2],[8,2.5,1.2,-0.15,26,12,10,4]];
ix: 1+rand(10);
W: L[ix][1]; c0: L[ix][2]; c1: L[ix][3]; c2: L[ix][4];
nF: L[ix][5]; nP: L[ix][6]; dx: L[ix][7]; dy: L[ix][8];
sqa: dx*dy;
est: nF+nP/2;
area: sqa*est;

feedbackvariables.text:
cok: is(abs(ans1-nF) <= 1 and abs(ans2-nP) <= 1);
dbl: is(ans1 >= nF+2 and abs(ans1+ans2-(nF+nP)) <= 2);
mis: is(abs(ans1-nF) <= 1 and ans2 <= nP-2);
